tokens:
--scheme: dark;
color-scheme: dark;
--bg: #0b1315;
--bg2: #0f1a1d;
--surface: #132124;
--surface2: #1a2c30;
--ink: #eef6f4;
--muted: #c8d9d5;
--faint: #9fb5b0;
--cardmeta: #dbe8e5;
--gold: #ffb547;
--gold-soft: #ffd28a;
--gold-deep: #8a5a14;
--on-gold: #1a1206;
--ink-soft: #c8d9d5;
--line: rgba(238, 246, 244, 0.12);
--line-strong: rgba(111, 227, 196, 0.45);
--ok: #7fe39a;
--warn: #ffcf5c;
--bad: #ff8f7a;
--shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 18px 50px rgba(0, 0, 0, 0.65);
--elev-1: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 2px 8px rgba(0, 0, 0, 0.45);
--elev-2: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 12px 30px rgba(0, 0, 0, 0.55);
--elev-3: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 28px 80px rgba(0, 0, 0, 0.75);
--scrim: rgba(0, 0, 0, 0.62);
--focus: #ffd28a;
--th-bg: #1a2c30;
--tabgrad1: #1a2c30; --tabgrad2: #132124;
--toastgrad1: #1a2c30; --toastgrad2: #132124;
--foot-bg: rgba(11, 19, 21, 0.94);
--drawerbar-bg: rgba(19, 33, 36, 0.96);
--ph-bg: #1a2c30;
--sel-bg: rgba(111, 227, 196, 0.16);
--row-hover: rgba(111, 227, 196, 0.07);
--hold-bg: linear-gradient(135deg, #1a2c30, #132124);
--skeleton1: #1a2c30; --skeleton2: #0b1315;
--grain-op: 0.04;
--wing-dur: 0.45s;
--wing-rise: 18px;
/* legacy aliases resolved on <html> */
--text: var(--ink); --panel: var(--surface); --chip: var(--surface2); --missing: var(--faint);
--border: var(--line); --gold-dim: var(--gold-deep); --danger: var(--bad);
--serif: "Futura", "Century Gothic", "Avenir Next", "Trebuchet MS", system-ui, sans-serif;
--mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
--radius: 8px;
/* the topo treatment (styles/style-layer.css, ui "topo"): contour hairlines */
--topo-line: rgba(111, 227, 196, 0.32);

